alter table public.classroom_accounts add column full_name text not null default '' check(char_length(full_name)<=200), add column additional_info text not null default '' check(char_length(additional_info)<=1000), add column profile_updated_at timestamptz, add column additional_updated_at timestamptz;
grant update(display_name,full_name,additional_info) on public.classroom_accounts to authenticated;
create policy "Admin edits classroom profile" on public.classroom_accounts for update to authenticated using((select classroom_private.is_admin())) with check((select classroom_private.is_admin()));
create function classroom_private.stamp_classroom_profile() returns trigger language plpgsql security invoker set search_path='' as $$begin new.profile_updated_at=now();if new.additional_info is distinct from old.additional_info then new.additional_updated_at=now();end if;return new;end $$;
revoke all on function classroom_private.stamp_classroom_profile() from public,anon;
grant execute on function classroom_private.stamp_classroom_profile() to authenticated;
create trigger stamp_classroom_profile before update on public.classroom_accounts for each row execute function classroom_private.stamp_classroom_profile();
alter table public.classroom_study_plans add column last_renewed_on date, add constraint classroom_renewal_dates check((last_renewed_on is null or started_on is null or last_renewed_on>=started_on) and(last_renewed_on is null or paid_until is null or last_renewed_on<paid_until));
create table public.classroom_renewals(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),course_id text not null references public.classroom_courses(id),renewed_on date not null,due_on date not null,recorded_at timestamptz not null default now(),unique(user_id,course_id,renewed_on),check(due_on>renewed_on));
create table public.classroom_mock_tests(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),course_id text not null references public.classroom_courses(id),tutor_id uuid not null references auth.users(id),name text not null check(char_length(name) between 1 and 200),starts_on date not null,ends_on date not null,through_level integer not null check(through_level between 1 and 200),status text not null default 'planned' check(status in('planned','done','cancelled')),score numeric,max_score numeric,completed_on date,note text not null default '' check(char_length(note)<=2000),created_at timestamptz not null default now(),check(ends_on=starts_on+6),check((score is null and max_score is null) or (score>=0 and max_score>0 and score<=max_score)),check(status<>'done' or(score is not null and max_score is not null and completed_on is not null)));
create index classroom_mock_user_course on public.classroom_mock_tests(user_id,course_id,starts_on);
create index classroom_mock_tutor on public.classroom_mock_tests(tutor_id,starts_on);
create index classroom_renewal_user_course on public.classroom_renewals(user_id,course_id,renewed_on);
alter table public.classroom_renewals enable row level security;
alter table public.classroom_mock_tests enable row level security;
revoke all on public.classroom_renewals,public.classroom_mock_tests from public,anon,authenticated;
grant select,insert,update on public.classroom_renewals,public.classroom_mock_tests to authenticated;
grant all on public.classroom_renewals,public.classroom_mock_tests to service_role;
create policy "Own renewal or admin" on public.classroom_renewals for select to authenticated using(user_id=(select auth.uid()) or (select classroom_private.is_admin()));
create policy "Admin records renewal" on public.classroom_renewals for insert to authenticated with check((select classroom_private.is_admin()));
create policy "Admin corrects renewal" on public.classroom_renewals for update to authenticated using((select classroom_private.is_admin())) with check((select classroom_private.is_admin()));
create policy "Own mock or admin" on public.classroom_mock_tests for select to authenticated using(user_id=(select auth.uid()) or (select classroom_private.is_admin()));
create policy "Admin creates mock" on public.classroom_mock_tests for insert to authenticated with check((select classroom_private.is_admin()));
create policy "Admin updates mock" on public.classroom_mock_tests for update to authenticated using((select classroom_private.is_admin())) with check((select classroom_private.is_admin()));
create function classroom_private.record_classroom_renewal() returns trigger language plpgsql security invoker set search_path='' as $$begin if new.last_renewed_on is not null and new.paid_until is not null then insert into public.classroom_renewals(user_id,course_id,renewed_on,due_on) values(new.user_id,new.course_id,new.last_renewed_on,new.paid_until) on conflict(user_id,course_id,renewed_on) do update set due_on=excluded.due_on;end if;return new;end $$;
revoke all on function classroom_private.record_classroom_renewal() from public,anon;
grant execute on function classroom_private.record_classroom_renewal() to authenticated;
create trigger record_classroom_renewal after insert or update on public.classroom_study_plans for each row execute function classroom_private.record_classroom_renewal();
